// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;

    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);

        // The log we register: its AddMessage always reverts.
        BadLog log = new BadLog();
        // The caller: a code-bearing contract whose fallback succeeds silently
        // (so in the mutant, the misdirected AddMessage to msg.sender succeeds).
        SilentCaller caller = new SilentCaller();

        vm.prank(address(caller));
        c.SetLogFile(address(log));

        vm.deal(address(caller), amount);
        vm.prank(address(caller));
        bool ok;
        try c.Put{value: amount}(0) { ok = true; } catch { ok = false; }

        // General rule: with a log whose AddMessage reverts, any Put must revert.
        assertTrue(ok == false);
    }
}

contract BadLog {
    function AddMessage(address, uint, string calldata) external pure {
        revert();
    }
}

contract SilentCaller {
    fallback() external payable {}
}
